    if dims_str_pair.x is None or dims_str_pair.y is None:
        return None

    specs_pair: Pair[list[DimSpec]] = Pair(
        x=parse_dims(dims_str_pair.x).dims,
        y=parse_dims(dims_str_pair.y).dims,
    )

