    atoms_y: list[str] = _atoms(specs_pair.y)
    if set(atoms_x) != set(atoms_y):
        _warn_dim_mismatch(atoms_x, atoms_y)
        return None

    groups_x: list[tuple[str, ...]] = _fused_groups(specs_pair.x)
    groups_y: list[tuple[str, ...]] = _fused_groups(specs_pair.y)
    conflict: Optional[tuple[tuple[str, ...], tuple[str, ...]]] = _find_fused_conflict(
        groups_x, groups_y
    )
    if conflict is not None:
        _warn_fused_conflict(conflict[0], conflict[1])
        return None

    member_to_group: dict[str, tuple[str, ...]] = {
        member: group for group in _dedupe_groups(groups_x + groups_y) for member in group
    }

    target_units: list[_TargetUnit] = _target_units(specs_pair.y, member_to_group)

    pattern: Pair[Optional[str]] = Pair(
        x=_build_side_pattern(specs_pair.x, target_units),
        y=_build_side_pattern(specs_pair.y, target_units),
    )

    if pattern.x is None and pattern.y is None:
        return None

    return AxisAlignerPlan(pattern=pattern)


def _atoms(specs: list[DimSpec]) -> list[str]:
    """Ordered atomic (sub-)dim names, ignoring squeeze dims.

    A fused dim expands to its sub-dim names; a regular dim is its single name.
    """
    return [
        sub_name
        for spec in specs
        if not _SingletonDimUtil.is_squeeze(spec)
        for sub_name in spec.sub_dims
    ]


def _fused_groups(specs: list[DimSpec]) -> list[tuple[str, ...]]:
    return [tuple(spec.sub_dims) for spec in specs if spec.is_fused]


def _dedupe_groups(groups: list[tuple[str, ...]]) -> list[tuple[str, ...]]:
    """Drop duplicate groups (identical membership), preserving first-seen order."""
    result: list[tuple[str, ...]] = []
    seen: set[frozenset[str]] = set()
    for group in groups:
        key = frozenset(group)
        if key not in seen:
            seen.add(key)
            result.append(group)
    return result


def _find_fused_conflict(
    groups_x: list[tuple[str, ...]], groups_y: list[tuple[str, ...]]
) -> Optional[tuple[tuple[str, ...], tuple[str, ...]]]:
    """Return the first incompatible (gx, gy) pair, or None if all are compatible.

    Two fused groups are incompatible when they share at least one member but are
    not identical (different membership or different sub-dim ordering).
    """
    for gx in groups_x:
        for gy in groups_y:
            if set(gx) & set(gy) and gx != gy:
                return gx, gy
    return None


