    added: set[object] = set()

    for spec in y_specs:
        if _SingletonDimUtil.is_squeeze(spec):
            continue
        for atom in spec.sub_dims:
            group: Optional[tuple[str, ...]] = member_to_group.get(atom)
            if group is not None:
